package cn.zhuatech.dqm.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class DataProductReleaseService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.ownerAssigned())b.add("数据产品未指定责任人");if(!r.dataContractApproved())b.add("数据契约未批准");if(!r.schemaCompatible())b.add("结构变更不兼容");if(!r.lineageComplete())b.add("端到端血缘不完整");if(r.criticalRuleFailures()>0)b.add("存在关键质量规则失败");if(!r.sensitiveDataClassified())b.add("敏感数据未完成分类");if(!b.isEmpty()){a.add("阻断发布并修复契约、结构、血缘和质量控制");return new Assessment(Decision.BLOCKED,b,a);}if(r.qualityScore()<90||r.freshnessAgeMinutes()>r.freshnessSlaMinutes()){if(r.qualityScore()<90)a.add("将数据质量分提升至至少 90");if(r.freshnessAgeMinutes()>r.freshnessSlaMinutes())a.add("恢复刷新 SLA 并重跑验证");return new Assessment(Decision.REVIEW,b,a);}a.add("发布数据产品并冻结契约、质量和血缘快照");return new Assessment(Decision.PUBLISH,b,a);}public record Request(@NotBlank String dataProduct,boolean ownerAssigned,boolean dataContractApproved,boolean schemaCompatible,boolean lineageComplete,@Min(0)int criticalRuleFailures,boolean sensitiveDataClassified,@Min(0)@Max(100)int qualityScore,@Min(0)int freshnessAgeMinutes,@Min(1)int freshnessSlaMinutes){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{PUBLISH,REVIEW,BLOCKED}}
